/**
 * TranscriptExtractorPort - Interface for transcript extraction from YouTube
 */

import { AppError } from '@core/errors/index.js';
import type { Result } from '@core/utils/result.js';
import { LanguageCode } from '../language-code.js';
import { Transcript } from '../transcript.js';
import { VideoId } from '../video-id.js';

/**
 * Available transcript languages response
 */
export interface AvailableLanguages {
  /** Language code */
  code: string;
  /** Human-readable language name */
  name: string;
  /** Whether this is auto-generated */
  isAutoGenerated: boolean;
  /** Whether this is a translation */
  isTranslation: boolean;
}

/**
 * Port interface for transcript extraction
 * Implementations: YoutubeTranscriptApiAdapter, YtDlpAdapter
 */
export interface TranscriptExtractorPort {
  /**
   * Extract transcript for a video
   * @param videoId - The video ID to extract transcript from
   * @param language - Preferred language (will try to find best match)
   * @returns Transcript or error
   */
  extract(videoId: VideoId, language?: LanguageCode): Promise<Result<Transcript, AppError>>;

  /**
   * Get available languages for a video
   * @param videoId - The video ID to check
   * @returns List of available languages
   */
  getAvailableLanguages(videoId: VideoId): Promise<Result<AvailableLanguages[], AppError>>;

  /**
   * Check if extractor is available/healthy
   */
  isHealthy(): Promise<Result<boolean, AppError>>;

  /**
   * Get extractor name/identifier
   */
  readonly name: string;

  /**
   * Get extractor priority (lower = higher priority, used for fallback chain)
   */
  readonly priority: number;
}

/**
 * Configuration for transcript extractors
 */
export interface TranscriptExtractorConfig {
  /** Timeout in milliseconds */
  timeoutMs: number;
  /** Maximum retry attempts */
  maxRetries: number;
  /** User agent string */
  userAgent: string;
  /** Default language */
  defaultLanguage: string;
}
